(93002, 9001, 2, 4, 'ANALYSIS', 'ABNORMAL', '{"verdict":"ABNORMAL","summary":"收入增长较快，订货对全年收入形成支撑；但利润增速低于收入增速，DSO 有所恶化，需重点关注盈利质量和回款风险。","findings":[{"severity":"HIGH","subject":"收入利润增长背离","message":"收入同比 +26.4%，利润同比仅 +8.2%。","evidence":["第8页","第12页"],"reason":"业务结构变化 / 毛利率下降 / 费用增长","suggestion":"复核收入与利润口径，重点检查盈利质量"},{"severity":"HIGH","subject":"回款质量恶化","message":"收入同比 +26.4%，回款仅 +18.2%，DSO 同比增加 12 天。","evidence":["第15页"],"reason":"回款增速低于收入增速，应收周转变慢","suggestion":"跟踪重点客户回款，制定回款改善计划"},{"severity":"HIGH","subject":"收入风险","message":"收入风险金额 12.6 亿元，风险占比 8.4%。","evidence":["第18页"],"reason":"部分重点项目交付延期，预计影响收入确认","suggestion":"关注重点项目交付进度与收入确认时点"},{"severity":"MEDIUM","subject":"全年目标压力","message":"全年收入预测 360 亿元，当前目标达成率 82%。","evidence":["第20页"],"reason":"H1 达成率与全年预测之间存在缺口","suggestion":"复核下半年收入计划与订单储备"},{"severity":"LOW","subject":"拨备关注","message":"拨备金额 3.2 亿元，拨备率 2.1%。","evidence":["第21页"],"reason":"拨备水平需要结合风险金额持续观察","suggestion":"跟踪拨备覆盖变化"}]}', 'ACTIVE', 1, NULL, CURRENT_TIMESTAMP),
(93003, 9002, 2, 3, 'PRE_AUDIT', 'NEED_CONFIRM', '{"verdict":"NEED_CONFIRM","summary":"材料基本可用，需人工确认目标达成口径","findings":[{"severity":"MEDIUM","message":"预测数据完整但目标达成进度偏慢，建议人工确认"}]}', 'ACTIVE', 1, NULL, CURRENT_TIMESTAMP),
(93004, 9002, 2, 4, 'ANALYSIS', 'ABNORMAL', '{"verdict":"ABNORMAL","summary":"经营保持平稳增长，盈利质量稳定；DSO 同比小幅上升，需关注回款节奏及全年目标达成压力。","findings":[{"severity":"MEDIUM","subject":"DSO 同比上升","message":"DSO 96 天，同比增加 6 天，回款率 85.2% 偏低。","evidence":["第12页"],"reason":"回款增速低于收入增速","suggestion":"加强应收账款回款跟进"},{"severity":"MEDIUM","subject":"全年目标压力","message":"收入目标达成率 76%，全年收入预测 186 亿元。","evidence":["第14页"],"reason":"上半年达成进度偏慢","suggestion":"复核全年目标与预测缺口"},{"severity":"LOW","subject":"收入风险","message":"收入风险金额 5.4 亿元，风险占比 6.6%。","evidence":["第16页"],"reason":"个别项目存在交付不确定性","suggestion":"持续跟踪风险项目进展"}]}', 'ACTIVE', 1, NULL, CURRENT_TIMESTAMP);
